// Select sendable: re-validate every row Notion returned. Pure selection, writes nothing.
const CAP = 5;
const TYPES = ["Estimate", "Reply", "Content"];
const txt = v => !v ? "" : v.title ? v.title.map(t => t.plain_text).join("") : v.rich_text ? v.rich_text.map(t => t.plain_text).join("") : v.select ? (v.select.name || "") : "";
const prop = (pr, name) => { for (const k in pr) if (k.toLowerCase() === name) return pr[k]; return null; };
const view = p => {
  const pr = p.properties || {};
  let title = "";
  for (const k in pr) if (pr[k] && pr[k].type === "title") title = txt(pr[k]);
  return { id: p.id, title: title || "(untitled)", status: txt(prop(pr, "status")), type: txt(prop(pr, "type")),
    qa: txt(prop(pr, "qa result")), decided_by: txt(prop(pr, "decided by")), draft: txt(prop(pr, "draft")).trim(),
    decided_at: ((prop(pr, "decided at") || {}).date || {}).start || "", edited: p.last_edited_time || "", created: p.created_time || "" };
};
// Returns "" when the row may be sent, else the reason it must be skipped.
const problem = v => {
  if (v.status !== "Approved") return "status is not Approved (" + (v.status || "empty") + ")";
  if (v.qa === "Fail" && !v.decided_by) return "QA Fail without Decided By";
  if (!TYPES.includes(v.type)) return "type not whitelisted (" + (v.type || "empty") + ")";
  if (!v.draft) return "Draft is empty";
  return "";
};
const skipped = [];
const ok = [];
for (const it of $input.all()) {
  const p = it.json;
  if (!p || !p.id) continue;
  const v = view(p);
  const why = problem(v);
  if (why) skipped.push({ id: v.id, title: v.title, reason: why }); else ok.push(v);
}
ok.sort((a, b) => String(a.decided_at || a.created).localeCompare(String(b.decided_at || b.created)));
const picked = ok.slice(0, CAP);
const deferred = ok.length - picked.length;
const summary = { seen: $input.all().filter(i => i.json && i.json.id).length, eligible: ok.length, picked: picked.length, deferred, skipped };
return [{ json: { kind: "summary", summary } }, ...picked.map(v => ({ json: { kind: "candidate", id: v.id, title: v.title, type: v.type, draft: v.draft, decided_at: v.decided_at } }))];

const s = $('Select sendable').first().json.summary;
const notes = "Send step selection. DRY_RUN is decided later. seen=" + s.seen + " eligible=" + s.eligible + " picked=" + s.picked + " deferred=" + s.deferred + " skipped=" + s.skipped.length + (s.skipped.length ? ". Skipped: " + s.skipped.slice(0, 10).map(x => x.title + " (" + x.reason + ")").join("; ") : "");
return [{ json: { task: "Send step: selection", status: "Done", notes: notes.slice(0, 1900) } }];

// Recheck and decide: runs on pages freshly re-fetched from Notion, immediately before any send.
// SAFE BY DEFAULT: while DRY_RUN is true nothing is ever marked Sent and no item reaches the sender.
// Joshua flips this to false only at go-live (see SEND.md).
const DRY_RUN = true;
const GRACE_MS = 5 * 60 * 1000; // Decided At is typed by a human around the same time as Status
const TYPES = ["Estimate", "Reply", "Content"];
const txt = v => !v ? "" : v.title ? v.title.map(t => t.plain_text).join("") : v.rich_text ? v.rich_text.map(t => t.plain_text).join("") : v.select ? (v.select.name || "") : "";
const prop = (pr, name) => { for (const k in pr) if (k.toLowerCase() === name) return pr[k]; return null; };
const view = p => {
  const pr = p.properties || {};
  let title = "";
  for (const k in pr) if (pr[k] && pr[k].type === "title") title = txt(pr[k]);
  return { id: p.id, title: title || "(untitled)", status: txt(prop(pr, "status")), type: txt(prop(pr, "type")),
    qa: txt(prop(pr, "qa result")), decided_by: txt(prop(pr, "decided by")), draft: txt(prop(pr, "draft")).trim(),
    decided_at: ((prop(pr, "decided at") || {}).date || {}).start || "", edited: p.last_edited_time || "", created: p.created_time || "" };
};
// Returns "" when the row may be sent, else the reason it must be skipped.
const problem = v => {
  if (v.status !== "Approved") return "status is not Approved (" + (v.status || "empty") + ")";
  if (v.qa === "Fail" && !v.decided_by) return "QA Fail without Decided By";
  if (!TYPES.includes(v.type)) return "type not whitelisted (" + (v.type || "empty") + ")";
  if (!v.draft) return "Draft is empty";
  return "";
};
const picked = {};
for (const it of $('Select sendable').all()) if (it.json && it.json.kind === "candidate") picked[it.json.id] = it.json;
const out = [];
for (const it of $input.all()) {
  const p = it.json;
  if (!p || !p.id || !picked[p.id]) continue;
  const v = view(p);
  const base = { id: v.id, title: v.title, type: v.type, draft: v.draft, dry_run: DRY_RUN };
  const why = problem(v);
  if (why) { out.push({ json: { ...base, decision: "skip", reason: why } }); continue; }
  const dAt = v.decided_at.length <= 10 ? Date.parse(v.decided_at + "T23:59:59.999Z") : Date.parse(v.decided_at);
  const edited = Date.parse(v.edited);
  if (!dAt || !edited) { out.push({ json: { ...base, decision: "skip", reason: "missing Decided At or Last Edited; cannot verify no edits after approval" } }); continue; }
  if (edited > dAt + GRACE_MS || v.draft !== picked[v.id].draft) {
    out.push({ json: { ...base, decision: "reset", reason: "edited after approval; Status returns to Awaiting Approval (schema rule 4)" } });
    continue;
  }
  out.push({ json: { ...base, decision: DRY_RUN ? "would_send" : "send", reason: DRY_RUN ? "DRY_RUN is true: would send, nothing sent" : "re-checked Approved, unedited" } });
}
return out;

const items = $input.all().map(i => i.json).filter(j => j && j.id);
const n = d => items.filter(j => j.decision === d);
const dry = items.length ? items[0].dry_run : true;
const list = d => n(d).map(j => j.title).join("; ");
const notes = "DRY_RUN=" + dry + ". would_send=" + n("would_send").length + " send=" + n("send").length + " reset=" + n("reset").length + " skip=" + n("skip").length +
  (n("would_send").length ? ". Would send: " + list("would_send") : "") + (n("send").length ? ". Sending: " + list("send") : "") +
  (n("reset").length ? ". Reset to Awaiting Approval: " + list("reset") : "") + (n("skip").length ? ". Skipped: " + n("skip").map(j => j.title + " (" + j.reason + ")").join("; ") : "");
return [{ json: { task: "Send step: " + (dry ? "dry run" : "live") + " result", status: "Done", notes: notes.slice(0, 1900) } }];

// Confirm send result: only an item the sender explicitly flags send_ok === true counts as success.
// A disabled or missing sender passes items through untouched, so nothing here is ever "confirmed" by default.
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  out.push({ json: { ...j, confirmed: j.decision === "send" && j.dry_run === false && j.send_ok === true } });
}
return out;
